#include "performance.h"
#include <cassert>
#include <cmath>
#include <cstdio>
#include <memory>
int main(){using namespace groove;auto serial_project=std::make_unique<ProjectState>();make_empty_project(*serial_project);serial_project->tracks[0].instrument=Instrument::DaisyAnalogDrums;serial_project->tracks[0].engine_parameters[0]=0;auto& group=serial_project->routing.groups[0];group.members=1;group.insert_fx[0]=11;group.insert_fx[1]=.8f;group.insert_fx[4]=15;group.insert_fx[5]=.7f;group.insert_fx[6]=.6f;track_at(*serial_project,0,0).level=.08f;auto parallel_project=std::make_unique<ProjectState>(*serial_project);parallel_project->routing.groups[0].parallel=1;
 auto serial=std::make_unique<Engine>(8000),parallel=std::make_unique<Engine>(8000);assert(serial->stage_project(*serial_project) && parallel->stage_project(*parallel_project));float a[128],b[128];serial->render(a,0);parallel->render(b,0);for(unsigned n=0;n<70;++n){serial->render(a,64);parallel->render(b,64);}assert(parallel->group_effect_target(0,10)==1);assert(serial->submit({CommandType::Trigger,0,0,127}) && parallel->submit({CommandType::Trigger,0,0,127}));float diff=0,energy=0;for(unsigned n=0;n<64;++n){serial->render(a,64);parallel->render(b,64);for(unsigned i=0;i<128;++i){assert(std::isfinite(a[i]) && std::isfinite(b[i]));diff+=fabsf(a[i]-b[i]);energy+=fabsf(a[i]);}}assert(energy>1 && diff>.05f);
 auto ui=std::make_unique<Performance>(*parallel,*parallel_project);ui->set_mode(UiMode::Routing);assert(ui->soft_key(0) && ui->soft_key(3) && ui->group_send_page());assert(ui->knob(7,-1000));assert(parallel_project->routing.groups[0].parallel<1);ui->set_shift(true);assert(ui->pad(15,0x10,3500) && ui->pad(15,0x20,0));assert(ui->knob(7,-1000));bool found=false;for(const auto& lock:track_at(*parallel_project,0,0).steps[3].locks)if(lock.enabled && lock.id==464)found=true;assert(found);ui.reset();serial.reset();parallel.reset();serial_project->routing.groups[0].insert_fx[0]=serial_project->routing.groups[0].insert_fx[4]=0;parallel_project->routing.groups[0].insert_fx[0]=parallel_project->routing.groups[0].insert_fx[4]=0;parallel_project->routing.groups[0].parallel=1;serial=std::make_unique<Engine>(8000);parallel=std::make_unique<Engine>(8000);assert(serial->stage_project(*serial_project) && parallel->stage_project(*parallel_project));serial->render(a,0);parallel->render(b,0);for(unsigned n=0;n<70;++n){serial->render(a,64);parallel->render(b,64);}assert(serial->submit({CommandType::Trigger,0,0,127}) && parallel->submit({CommandType::Trigger,0,0,127}));float max_difference=0,unity_energy=0;for(unsigned n=0;n<64;++n){serial->render(a,64);parallel->render(b,64);for(unsigned i=0;i<128;++i){max_difference=fmaxf(max_difference,fabsf(a[i]-b[i]));unity_energy+=fabsf(a[i]);}}assert(unity_energy>1 && max_difference<.000001f);puts("group serial/parallel audio, bypass unity, blend control and step lock passed");}
